import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthPage, ProfilePage, ManagerDashboardNew, ProtectedRoute, EnhancedBillUpload, Layout } from "./components";
import TripBudgetDashboard from "./components/TripBudgetDashboard";
import TripDebugger from "./components/TripDebugger";
import EnhancedAuthPage from "./components/EnhancedAuthPage";
import "./styles.css";

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={<EnhancedAuthPage />} />
          <Route path="/register" element={<EnhancedAuthPage />} />

          {/* Protected Routes with Navigation */}
          <Route 
            path="/profile" 
            element={
              <ProtectedRoute>
                <Layout>
                  <ProfilePage />
                </Layout>
              </ProtectedRoute>
            } 
          />
          {/* Primary Bill Upload Route - Enhanced Processing */}
          <Route 
            path="/upload" 
            element={
              <ProtectedRoute>
                <Layout>
                  <EnhancedBillUpload />
                </Layout>
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/enhanced-upload" 
            element={
              <ProtectedRoute>
                <Layout>
                  <EnhancedBillUpload />
                </Layout>
              </ProtectedRoute>
            } 
          />

          {/* Trip Budget Dashboard */}
          <Route 
            path="/budget" 
            element={
              <ProtectedRoute>
                <Layout>
                  <TripBudgetDashboard />
                </Layout>
              </ProtectedRoute>
            } 
          />

          {/* Debug Route */}
          <Route 
            path="/debug" 
            element={
              <ProtectedRoute>
                <Layout>
                  <TripDebugger />
                </Layout>
              </ProtectedRoute>
            } 
          />

          {/* Manager Dashboard */}
          <Route 
            path="/team-bills" 
            element={
              <ProtectedRoute>
                <Layout>
                  <ManagerDashboardNew />
                </Layout>
              </ProtectedRoute>
            } 
          />

          {/* Default redirect */}
          <Route path="/" element={<Navigate to="/upload" replace />} />
          <Route path="*" element={<Navigate to="/upload" replace />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
